Translate("zhCN", "silverpine-forest", {
	title = "银松森林",
	aliases = { "银松" },
	sections = {
		{
			title = "概述",
			text = [=[银松森林从{link:tirisfal-glades}提瑞斯法{/link}的{link:moonglade}林地{/link}向南延伸，直到{link:gilneas}吉尔尼斯{/link}的巨墙。幽暗的松树挤满了它的山丘，在东面，它的湖岸没入{red:lordamere-lake}洛丹米尔湖{/red}灰色的湖水之中。它曾是一片农场、果园与磨坊遍布的宁静乡野。如今它是亡者与被诅咒者的土地。{link:forsaken}被遗忘者{/link}从{link:the-sepulcher}瑟伯切尔{/link}控制着它的道路，{link:scourge}天灾军团{/link}占据着湖中一座岛上的要塞，而在山丘中嚎叫的，是一位{link:dalaran}达拉然{/link}疯狂大法师的狼人。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载第一批{link:humans}人类{/link}在何年定居银松，也没有记载是哪位领主首先宣称拥有它。这里的人们在{link:stranglethorn-vale}山谷{/link}中耕种，照料果园，经营磨坊。在{link:pyrewood-village}焚木村{/link}的上方，矗立着贵族{link:baron-silverlaine}席瓦莱恩男爵{/link}的城堡。当国王{link:genn-greymane}吉恩·格雷迈恩{/link}在{link:second-war}第二次战争{/link}之后封锁了他的王国，{link:the-greymane-wall}格雷迈恩之墙{/link}便横跨森林南部拔地而起，{link:gilneas}吉尔尼斯{/link}的大门在墙后关闭。银松的居民被留在了北侧。]=],
		},
		{
			title = "当今",
			text = [=[{link:sylvanas-windrunner}黑暗女王{/link}把夺取南方土地的任务交给了她的副官{link:varimathras}瓦里玛萨斯{/link}，银松是第一步。{link:high-executor-hadrec}高级执行官哈德瑞克{/link}在{link:the-sepulcher}瑟伯切尔{/link}统领{link:forsaken}被遗忘者{/link}，但他的敌人众多。腐皮{link:gnolls}豺狼人{/link}由叛徒法师{link:thule-ravenclaw}图勒·鸦爪{/link}唤起并操控，它们把尸体从{link:tirisfal-glades}提瑞斯法{/link}运往{link:fenris-isle}芬里斯岛{/link}。{link:archmage-arugal}大法师阿鲁高{/link}的狼人在林中狩猎，{link:pyrewood-village}焚木村{/link}的村民每到夜晚便化为野兽。在{link:ambermill}安伯米尔{/link}，{link:dalaran}达拉然{/link}的巫师们在进行他们自己的秘密工作，并以强硬的手段把守道路。在{link:the-greymane-wall}格雷迈恩之墙{/link}前，惊恐的{link:humans}人类{/link}难民聚集在不会打开的大门前。

这些日子里，{link:tyr-s-watch}提尔守望{/link}的圣骑士派了一名使者到瑟伯切尔，一位{link:skyborne}天裔{/link}旅人也来到了森林，带来了她的悲伤。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:forsaken}被遗忘者{/link}。{/b} 死亡守卫、亡灵{link:sentinels}哨兵{/link}、药剂师和一位已死的{link:dalaran}达拉然{/link}大法师，全都从{link:the-sepulcher}瑟伯切尔{/link}为{link:sylvanas-windrunner}黑暗女王{/link}效力。
• {b}{link:scourge}天灾军团{/link}。{/b} 腐皮{link:gnolls}豺狼人{/link}、{link:thule-ravenclaw}图勒·鸦爪{/link}的仆从以及旧农场里没有心智的亡者。
• {b}狼人。{/b} 狂月狼人与{link:archmage-arugal}阿鲁高{/link}之子，这些野性的狼人在某种程度上听命于{link:shadowfang-keep}影牙城堡{/link}的大法师。
• {b}{link:pyrewood-villagers}焚木村的被诅咒者{/link}。{/b} 白天是{link:humans}人类{/link}、夜晚是野兽的村民。
• {b}{link:the-wizards-of-ambermill}安伯米尔的巫师{/link}。{/b} {link:kirin-tor}肯瑞托{/link}的法师及其卫兵，对北方的生者和亡者都不友好。
• {b}野兽与鱼人。{/b} 座狼、灰熊、巨型蜘蛛以及湖岸的邪鳍{link:murlocs}鱼人{/link}。]=],
		},
		{
			title = "历史",
			text = [=[• {b}瘟疫。{/b} 在{link:third-war}第三次战争{/link}中，瘟疫席卷了{link:lordaeron}洛丹伦{/link}。银松北部的农夫死在自己的土地上，又作为{link:scourge}天灾军团{/link}的一员复起。
• {b}狼人。{/b} {link:dalaran}达拉然{/link}的巫师在森林中与天灾军团作战，而他们自己的死者起身反抗他们。{link:archmage-arugal}大法师阿鲁高{/link}不顾同僚的劝告，召唤了来自世界之外的力量，于是狼人来了。它们屠戮了亡者，随后转而攻击巫师。它们夺取了{link:baron-silverlaine}席瓦莱恩男爵{/link}的城堡，阿鲁高将其据为己有。
• {b}{link:forsaken}被遗忘者{/link}。{/b} 后来，被遗忘者从{link:tirisfal-glades}提瑞斯法{/link}南下，把{link:the-sepulcher}瑟伯切尔{/link}作为他们在森林中的据点。]=],
		},
		{
			title = "森林的传说",
			text = [=[• 药剂师们说，很久以前，一场瘟疫杀死了洛丹米尔湖水中的一切生灵。
• 三位年轻的法师曾用他们的学徒魔杖编成一根魔杖，作为友谊的象征。其中一人就是{link:thule-ravenclaw}图勒·鸦爪{/link}。
• {link:the-sepulcher}瑟伯切尔{/link}的一位已死的大法师声称，{link:archmage-arugal}阿鲁高{/link}根本就没有制造狼人的力量。]=],
		},
	},
})

Translate("zhCN", "the-sepulcher", {
	title = "瑟伯切尔",
	aliases = { "银松瑟伯切尔" },
	sections = {
		{
			title = "概述",
			text = [=[瑟伯切尔是{link:forsaken}被遗忘者{/link}在{link:silverpine-forest}银松{/link}的据点。它坐落在森林中心一座林木覆盖的山丘上，是一片古老的墓地，如今亡者在这里守望着生者的世界。{link:high-executor-hadrec}高级执行官哈德瑞克{/link}从这里派出他的亡灵{link:sentinels}哨兵{/link}，死亡守卫则把守着道路。一位已死的大法师研究狼人的诅咒，一位暗影牧师搜集每一条消息，一位协会的药剂师在研制新的瘟疫。蝙蝠载着骑手向北飞往{link:undercity}幽暗城{/link}。这些日子里，瑟伯切尔还收留着一位{link:tyr-s-watch}提尔守望{/link}的使者和一位{link:skyborne}天裔{/link}年轻女子。]=],
		},
	},
})

Translate("zhCN", "pyrewood-village", {
	title = "焚木村",
	aliases = { "焚木" },
	sections = {
		{
			title = "概述",
			text = [=[焚木村是{link:silverpine-forest}银松{/link}南部的一个小村庄，位于{link:shadowfang-keep}影牙城堡{/link}的城墙之下。白天，它看起来和其他任何{link:humans}人类{/link}小村一样：一座镇公所，一家旅店，忙于工作的铁匠和裁缝，还有街上的守卫。太阳一落山，它的居民便变成狼人。{link:archmage-arugal}阿鲁高{/link}给他们所有人都戴上了附魔的镣铐，并通过村子自己的{link:shadow-council}议会{/link}统治这里，议会成员都是他的傀儡。旅店里有一位药剂师的书房，他也遭受了同样的诅咒。一名亡灵{link:sentinels}哨兵{/link}藏在镇公所里，等待议会成员回来。]=],
		},
	},
})

Translate("zhCN", "ambermill", {
	title = "安伯米尔",
	sections = {
		{
			title = "概述",
			text = [=[安伯米尔是{link:silverpine-forest}银松{/link}东南部山丘中的一个村庄，靠近洛丹米尔湖的湖岸。它从来不是什么重要的地方。然而{link:dalaran}达拉然{/link}的法师们却让这里挤满了巫师、咒术师和全副武装的守护者，还用马车从{link:hillsbrad-foothills}希尔斯布莱德{/link}运来一箱箱地图和刻有符文的坠饰。{link:forsaken}被遗忘者{/link}相信他们知道其中的原因。安伯米尔位于一个沉睡的魔网能量节点之上，一位大法师一直在努力唤醒它。{link:kirin-tor}肯瑞托{/link}打算用这样的力量做什么，{link:the-sepulcher}瑟伯切尔{/link}里没有人说得清。]=],
		},
	},
})

Translate("zhCN", "fenris-isle", {
	title = "芬里斯岛",
	sections = {
		{
			title = "概述",
			text = [=[芬里斯岛位于洛丹米尔湖中，在{link:the-decrepit-ferry}破旧渡口{/link}以东。它是{link:scourge}天灾军团{/link}在{link:silverpine-forest}银松{/link}的据点。腐皮{link:gnolls}豺狼人{/link}遍布它的湖岸和它那座破败的城堡。一条船把{link:tirisfal-glades}提瑞斯法{/link}的尸体从渡口运过湖面，在岛上，那些尸体为它们的新主人效力。邪鳍{link:murlocs}鱼人{/link}在岛上的沙滩上狩猎，长满苔藓的湖中野兽在芦苇间爬行。最近，死亡守卫看到豺狼人把一具巨大的尸体扔到岸边的火堆上。那是一个{link:tauren}牛头人{/link}的尸体。]=],
		},
	},
})

Translate("zhCN", "fenris-keep", {
	title = "芬里斯城堡",
	sections = {
		{
			title = "概述",
			text = [=[芬里斯城堡是{link:fenris-isle}芬里斯岛{/link}上的要塞。{link:thule-ravenclaw}图勒·鸦爪{/link}和他的腐皮{link:gnolls}豺狼人{/link}在那里统治。在城堡的院子里，靠近旧马厩的地方，豺狼人把一具无头的尸体埋进了一座无名坟墓。他们把头留下来当玩具。那颗头仍会说话。图勒的首席仆人阿拉里克在这座城堡里度过了他一生中最好的时光，他知道城堡的秘密，其中包括西南塔楼里的一个隐秘壁龛。最近，豺狼人还在城墙内的一个笼子里关着一名活着的囚徒。]=],
		},
	},
})

Translate("zhCN", "the-decrepit-ferry", {
	title = "破旧渡口",
	sections = {
		{
			title = "概述",
			text = [=[破旧渡口是洛丹米尔湖岸边的一座旧码头，位于{link:the-sepulcher}瑟伯切尔{/link}以东。它已经腐朽，几乎被人遗忘，但并没有闲置。{link:thule-ravenclaw}图勒·鸦爪{/link}的仆从守卫着它，腐皮{link:gnolls}豺狼人{/link}来来往往。停泊在那里的船上堆满了为运送而包裹好的尸体。在湖对岸，{link:fenris-isle}芬里斯岛{/link}上还有第二座码头。{link:forsaken}被遗忘者{/link}已经得知，这些尸体来自{link:tirisfal-glades}提瑞斯法{/link}的乱葬坑，其中有一位名叫德莉娅的{link:brill}布瑞尔{/link}女子，它们的旅程全都在岛上结束。]=],
		},
	},
})

Translate("zhCN", "the-dead-field", {
	title = "亡者农场",
	sections = {
		{
			title = "概述",
			text = [=[亡者农场是{link:silverpine-forest}银松{/link}北部一座废弃的农庄。腐皮{link:gnolls}豺狼人{/link}把这里变成了营地，监视营地的亡灵{link:sentinels}哨兵{/link}认为豺狼人正在备战。{link:forsaken}被遗忘者{/link}不止一次袭击他们，每一次都被一个名叫夜鞭的女妖击溃，她用自己的魔法援助豺狼人。{link:high-executor-hadrec}哈德瑞克{/link}想要消灭她。据说夜鞭倒下时，她的精华会化为尘土。]=],
		},
	},
})

Translate("zhCN", "the-ivar-patch", {
	title = "伊瓦农场",
	sections = {
		{
			title = "概述",
			text = [=[伊瓦农场曾是一个名叫{link:ivar-the-foul}伊瓦{/link}的人的农场，位于{link:silverpine-forest}银松{/link}的最北端。瘟疫来临时，伊瓦、他的大部分家人和他的雇工全都倒下，又作为{link:scourge}天灾军团{/link}的一员复起。伊瓦仍以食尸鬼的身份在他的谷仓中作祟。亡灵{link:sentinels}哨兵{/link}{link:rane-yorick}兰妮·尤瑞克{/link}和{link:quinn-yorick}奎恩·尤瑞克{/link}在执行任务时在这里遭到伏击，他们把伊瓦的旧房子当作了藏身之所。拉恩从窗口守望，奎恩在楼上养伤。]=],
		},
	},
})

Translate("zhCN", "malden-s-orchard", {
	title = "玛尔丁果园",
	sections = {
		{
			title = "概述",
			text = [=[玛尔丁果园位于{link:silverpine-forest}银松{/link}的东北角，靠近{link:tirisfal-glades}提瑞斯法{/link}的边界。它的果树无人采摘，曾住在农舍里的人也已不知去向。如今果园里满是座狼，多到一名被派去侦察的亡灵{link:sentinels}哨兵{/link}被困在农舍里好几天。座狼盯着门口，等着他出来。在它们之中，猎食着一头被称为{link:bloodtooth-camp}血牙{/link}的巨大黑色座狼。]=],
		},
	},
})

Translate("zhCN", "valgan-s-field", {
	title = "瓦尔甘牧场",
	sections = {
		{
			title = "概述",
			text = [=[瓦尔甘牧场是{link:silverpine-forest}银松{/link}北部的一座麦田农场，就在一条小河的桥北边。{link:archmage-arugal}大法师阿鲁高{/link}初到森林时，就住在这里。他留下了一些法术书，找到它们的亡灵{link:sentinels}哨兵{/link}却无法把它们带走。其中有一个被阿鲁高称为他的解药的法术。如今狼人在农场周围的土地上游荡。]=],
		},
	},
})

Translate("zhCN", "north-tide-s-hollow", {
	title = "北流谷",
	sections = {
		{
			title = "概述",
			text = [=[北流谷是{link:the-sepulcher}瑟伯切尔{/link}正北方的一片{link:moonglade}林地{/link}，朝向西面的大海。狂月狼人把这里当作他们的出没之所之一。它们的贪食者和黑魂者在树林间潜行，每一个都戴着{link:archmage-arugal}阿鲁高{/link}打造的附魔镣铐。瑟伯切尔那位已死的大法师仔细研究过这些镣铐。他说，它们是阿鲁高的魔法比世人所以为的更弱的第一个证据。]=],
		},
	},
})

Translate("zhCN", "olsen-s-farthing", {
	title = "奥森农场",
	sections = {
		{
			title = "概述",
			text = [=[奥森农场是主路旁一座破败的农庄，位于{link:the-sepulcher}瑟伯切尔{/link}以南。它曾与每一辆穿过森林的马车做买卖。如今农场已被亡者占据。为{link:thule-ravenclaw}图勒·鸦爪{/link}效力的劫掠者和奴隶聚集在那里，扑向任何靠近的人。{link:forsaken}被遗忘者{/link}每次走南边的道路，都必须从他们身边经过。]=],
		},
	},
})

Translate("zhCN", "the-skittering-dark", {
	title = "粘丝洞",
	sections = {
		{
			title = "概述",
			text = [=[粘丝洞是{link:silverpine-forest}银松{/link}西北部靠近大海的一处蛛网密布的洼地。巨大的苔藓潜伏者和雾行者在那里筑巢，熊在它的边缘游荡。{link:the-sepulcher}瑟伯切尔{/link}的药剂师们很看重这里蜘蛛的血。它与从灰熊心脏中提取的毒素混合，能制成一种致命的药剂，协会希望这会是通往新瘟疫的一步。一个{link:forsaken}被遗忘者{/link}渔夫在附近的岸边垂钓，仿佛那些蜘蛛与他毫不相干。]=],
		},
	},
})

Translate("zhCN", "deep-elem-mine", {
	title = "埃利姆矿洞",
	sections = {
		{
			title = "概述",
			text = [=[埃利姆矿洞位于{link:silverpine-forest}银松{/link}中部的山丘中，在{link:the-sepulcher}瑟伯切尔{/link}的东南方。{link:archmage-arugal}阿鲁高{/link}的魔法甚至蔓延到了这里，矿洞自己的工头，{link:grimson-the-pale}白毛狼人格瑞姆森{/link}，成了它的受害者。如今狂月狼人占据着矿道。{link:forsaken}被遗忘者{/link}想为即将到来的战争夺取这座矿洞，因为它的矿石能为{link:varimathras}瓦里玛萨斯{/link}向南方的推进提供补给。{link:dalar-dawnweaver}达拉尔·道恩维沃尔{/link}相信，只要工头一死，矿洞就会归{link:sylvanas-windrunner}黑暗女王{/link}所有。]=],
		},
	},
})

Translate("zhCN", "beren-s-peril", {
	title = "博伦的巢穴",
	sections = {
		{
			title = "概述",
			text = [=[博伦的巢穴是{link:ambermill}安伯米尔{/link}西南山丘中的一个洞穴，离{link:the-wizards-of-ambermill}达拉然巫师{/link}的一处营地不远。{link:forsaken}被遗忘者{/link}从他们的斥候那里得知，一群亡灵聚集在那里。为{link:thule-ravenclaw}图勒·鸦爪{/link}效力的苦工和守卫正在准备进攻{link:the-sepulcher}瑟伯切尔{/link}本身。{link:shadow-priest-allister}暗影牧师奥利斯特{/link}没有等他们出发。他派自己的密探进入洞穴，先发制人。]=],
		},
	},
})

Translate("zhCN", "gates-of-shadowfang-keep", {
	title = "影牙城堡大门",
	sections = {
		{
			title = "概述",
			text = [=[{link:shadowfang-keep}影牙城堡{/link}矗立在{link:silverpine-forest}银松{/link}南部的一座山丘上，就在{link:pyrewood-village}焚木村{/link}的北边。它曾是{link:baron-silverlaine}席瓦莱恩男爵{/link}的城堡，直到狼人夺取了它，{link:archmage-arugal}大法师阿鲁高{/link}将其作为自己的居所。从路上望去，城堡只露出它黑暗的城墙。阿鲁高之子从这里出发在森林中行走，这些巨大的狼人像孩子一样侍奉着大法师。{link:forsaken}被遗忘者{/link}派了亡灵{link:sentinels}哨兵{/link}进去。他们没有一个人回来。]=],
		},
	},
})

Translate("zhCN", "the-greymane-wall", {
	title = "格雷迈恩之墙",
	sections = {
		{
			title = "概述",
			text = [=[格雷迈恩之墙横贯{link:silverpine-forest}银松{/link}的南缘，把{link:gilneas}吉尔尼斯{/link}王国与北方隔绝开来。国王{link:genn-greymane}吉恩·格雷迈恩{/link}在{link:second-war}第二次战争{/link}之后建起了它，从那以后，它的大门一直紧闭，即便瘟疫来临时也是如此。在墙前，从北方逃来的{link:humans}人类{/link}建起了一座绝望者的营地。他们中许多人患了病。一个盲眼的铁匠在他们中间干活。狼人和座狼在附近潜行，{link:forsaken}被遗忘者{/link}担心诅咒正在传给难民。吉尔尼斯人已经明确表示，不会放任何人通过。]=],
		},
	},
})

Translate("zhCN", "pyrewood-villagers", {
	title = "焚木村村民",
	aliases = { "焚木村议会", "焚木村的被诅咒者" },
	sections = {
		{
			title = "概述",
			text = [=[{link:pyrewood-village}焚木村{/link}的村民过着两种生活。白天他们是{link:humans}人类{/link}：守卫、长者、铁匠、裁缝和制皮匠，各自忙于自己的工作。太阳落山时，{link:archmage-arugal}大法师阿鲁高{/link}的诅咒便发作，他们变成狂月狼人。他们每个人都戴着阿鲁高施加在他们身上的附魔镣铐。]=],
		},
		{
			title = "议会",
			text = [=[{link:pyrewood-village}焚木村{/link}仍由它的{link:shadow-council}议会{/link}治理，那是在市长莫里森领导下的八名议员。{link:forsaken}被遗忘者{/link}相信，议会已不再是它自己的主人。{link:archmage-arugal}阿鲁高{/link}利用他们作为傀儡，在他的注意力放在{link:shadowfang-keep}影牙城堡{/link}时，让村里的野兽保持顺从。{link:deathstalker-faerleia}亡灵哨兵费雷亚{/link}希望，一旦议会成员死去，狼人就会转而反抗阿鲁高本人。]=],
		},
		{ title = "未载", text = "没有任何编年史记载村民在白天是否记得他们夜里做过的事。也没有记载诅咒最初是何时降临到他们身上的。" },
	},
})

Translate("zhCN", "the-wizards-of-ambermill", {
	title = "安伯米尔的巫师",
	aliases = { "达拉然巫师", "安伯米尔的肯瑞托" },
	sections = {
		{
			title = "概述",
			text = [=[安伯米尔的巫师是{link:dalaran}达拉然{/link}的法师以及守护他们的仆从：学徒、咒术师、法师、{link:the-night-watch}守望者{/link}、守护者和保卫者，甚至还有一名酿酒师和一名矿工。他们听命于{link:kirin-tor}肯瑞托{/link}，并把{link:silverpine-forest}银松{/link}一个沉睡的村庄变成了他们自己的要塞。]=],
		},
		{
			title = "他们的工作",
			text = [=[{link:ambermill}安伯米尔{/link}坐落在一个长久休眠的魔网能量节点之上。{link:kirin-tor}肯瑞托{/link}正是因此选中了它，他们的{link:archmage-ataeric}大法师阿塔瑞克{/link}一直在编织节点的能量，使其苏醒，以达成某个宏大的目的。他们携带的刻有符文的坠饰是肯瑞托的古老工具，用于引导这样的力量。巫师们还在{link:pyrewood-village}焚木村{/link}北边有一处营地，他们从{link:hillsbrad-foothills}希尔斯布莱德{/link}运来的箱子就送到那里。]=],
		},
		{
			title = "生者与亡者之间",
			text = [=[对{link:forsaken}被遗忘者{/link}来说，{link:ambermill}安伯米尔{/link}是森林中{link:humans}人类{/link}抵抗的核心。自从{link:dalaran}达拉然{/link}的巨大屏障倒下以来，巫师们就一直把守着道路，不让任何人自由通过。他们究竟在害怕什么，他们没有说。]=],
		},
	},
})

