Translate("zhCN", "genn-greymane", {
	title = "吉恩·格雷迈恩",
	subtitle = "吉尔尼斯国王",
	found = "格雷迈恩之墙后方，吉尔尼斯境内",
	hint = "了解那位用城墙封锁银松南部的国王。",
	allegiance = "吉尔尼斯王国",
	aliases = { "格雷迈恩", "格雷迈恩国王", "吉恩·格雷迈恩国王" },
	sections = {
		{
			title = "概述",
			text = [=[吉恩·格雷迈恩是{link:gilneas}吉尔尼斯{/link}的国王。他是一位骄傲而固执的统治者，一位信任自己的人民却很少信任他人的战士。正是他在{link:second-war}第二次战争{/link}之后让吉尔尼斯退出了{link:alliance}联盟{/link}，也正是他在{link:silverpine-forest}银松{/link}南部建起了那道巨墙。在那道墙后，他的王国在北方的种种劫难中始终自行其是。]=],
		},
		{
			title = "意义",
			text = [=[格雷迈恩是一位选择独自屹立的君主。他的墙让{link:gilneas}吉尔尼斯{/link}免于承担其他国家战争的代价。它也让北方在没有吉尔尼斯军队的情况下独自面对{link:scourge}天灾军团{/link}。这道墙究竟拯救了他的王国，还是只是把它藏了起来，外面的人无从得知。]=],
		},
		{
			title = "事迹",
			text = [=[• {link:stormwind-city}暴风城{/link}陷落时，他与其他{link:humans}人类{/link}统治者一同来到{link:lordaeron}洛丹伦{/link}，参加由国王{link:terenas-menethil}泰瑞纳斯{/link}召集的会议。他怀疑危险的存在，并夸口说{link:gilneas}吉尔尼斯{/link}的军队足以应对任何威胁。
• 他勉强加入了{link:alliance}洛丹伦联盟{/link}，给予联盟的远远少于他的王国所能给予的。
